"""Independent original behavior, not expectations generated by the Rust port."""
import hashlib
import json
from pathlib import Path
import shutil

import pytest

from tools.rust_migration.reference import freeze_reference

ROOT = Path(__file__).resolve().parents[2]


@pytest.fixture
def original(tmp_path):
    source = tmp_path / 'source'
    shutil.copytree(ROOT / 'src', source / 'src', ignore=shutil.ignore_patterns('__pycache__'))
    helper = source / 'tests/retrieval/test_translation_preparation.py'
    helper.parent.mkdir(parents=True)
    shutil.copy2(ROOT / 'tests/retrieval/test_translation_preparation.py', helper)
    return freeze_reference(source, tmp_path / 'frozen')


def test_original_fixture_preserves_order_ascii_and_config_only_newline(original, tmp_path):
    from tools.rust_migration.translation_fixtures import generate_preparation
    result = generate_preparation(original, tmp_path / 'fixtures')
    assert result['original_helper_verified'] is True
    ready = Path(result['prepared'])
    assert (ready / 'config.json').read_bytes() == b'{\n  "bos_token": "<s>",\n  "x": false\n}\n'
    assert (ready / 'shared_vocabulary.json').read_bytes() == b'[\n  "<unk>",\n  "rojo",\n  "\\u00e1"\n]'
    assert (ready / 'model.bin').read_bytes() == b'weights'
    assert result['helper_sha256'] == hashlib.sha256(
        (original.root / 'tests/retrieval/test_translation_preparation.py').read_bytes()).hexdigest()
    saved = (tmp_path / 'fixtures/manifest.json').read_text()
    assert str(tmp_path) not in saved


def test_policy_oracle_pins_distinct_casefold_boundaries_and_match_priority(original, tmp_path):
    from tools.rust_migration.translation_unicode import generate_policy
    record = generate_policy(original, tmp_path / 'policy.json')
    assert record['scope'] == 'original-only-policy-characterization'
    assert record['unicode'] == '15.0.0'
    rows = {row['query']: row for row in record['cases']}
    assert len(record['cases']) == 2438
    assert rows['busca busca']['needs_translation'] is False
    assert rows['que qué']['needs_translation'] is True
    assert rows['buſca laſ']['needs_translation'] is True
    assert rows['İcómo convierte']['needs_translation'] is True
    assert rows['cómo\u0301 convierte']['needs_translation'] is True
    row = rows['¿Dónde se invoca `Client.send` con project_name?']
    assert row['protected'] == ['`Client.send`', 'project_name']
    assert row['prepared'] == '¿Dónde se invoca ZXQ0QXZ con ZXQ1QXZ?'
    assert rows['¿ a.b$']['protected'] == ['a.b']
    assert rows['¿ a_²']['protected'] == []
    assert rows['¿ a_١']['protected'] == ['a_١']
    many = rows['¿ ' + ' '.join(f'item_{i}' for i in range(24))]
    assert many['prepared'].endswith('ZXQ23QXZ')
    assert many['protected'][10] == 'item_10'


def test_unicode_contract_has_independent_whole_scalar_digest(original, tmp_path):
    from tools.rust_migration.translation_unicode import generate_unicode
    record = generate_unicode(original, tmp_path / 'unicode.json')
    assert record['unicode'] == '15.0.0'
    assert record['regex_predicates_verified'] is True
    assert record['digest'] == 'ade25dd6e59cf7919537e19af9070770bd3ec5ea50b5ad98c6948ea2ff495777'
    fold = dict(record['tables']['casefold'])
    assert fold[ord('ſ')] == 's'
    assert fold[ord('İ')] == 'i\u0307'


def test_original_restoration_includes_control_whitespace_and_literal_collisions(original, tmp_path):
    from tools.rust_migration.translation_unicode import generate_policy
    record = generate_policy(original, tmp_path / 'policy.json')
    assert record['restoration_scope'] == 'original-policy-only-controlled-decoder'
    rows = {row['id']: row for row in record['restoration']}
    assert rows['spaces-and-case']['output'] == 'Find `Client.send` and project_name.'
    assert rows['multi-digit']['output'] == 'item_0 / item_10 / item_23'
    assert rows['literal-collision']['output'] == '`x.y` `x.y`'
    assert rows['damaged-key']['output'] == 'ZXQ0QX?'
    assert rows['replacement-literal']['output'] == '`path\\raw.$1`'
    assert rows['whitespace-empty']['error'] == 'local query expansion produced empty text'


def test_tiny_english_capture_does_not_load_invalid_neural_data(original, tmp_path):
    from tools.rust_migration.translation_fixtures import generate_preparation
    from tools.rust_migration.translation_reference import capture
    fixture = generate_preparation(original, tmp_path / 'fixtures')
    cases = [{'id': 'english', 'queries': ['Where are names normalized?', '', 'busca busca']},
             {'id': 'missing-english', 'missing_assets': True, 'queries': ['find the input parser']}]
    result = capture(original, Path(fixture['source']), tmp_path / 'oracle.json',
                     cases=cases, definition=fixture['definition'])
    assert result['oracle']['frozen_import'] is True
    assert result['results'][0]['calls'][0]['output'] == 'Where are names normalized?'
    assert result['results'][0]['calls'][1]['output'] == ''
    assert result['results'][0]['calls'][2]['output'] == 'busca busca'
    assert result['results'][1]['calls'][0]['output'] == 'find the input parser'
    assert all(call['runtime_loaded'] is False for row in result['results'] for call in row['calls'])
    assert all(call['trace'] == {} for row in result['results'] for call in row['calls'])
    assert result['recipe_sha256'] == hashlib.sha256(
        json.dumps(fixture['definition'], sort_keys=True).encode()).hexdigest()
    assert json.loads((tmp_path / 'oracle.json').read_text()) == result


def test_oracles_reject_frozen_source_drift_before_capturing(original, tmp_path):
    from tools.rust_migration.translation_unicode import generate_policy
    path = original.root / 'src/ken/retrieval/query_expansion.py'
    path.write_text(path.read_text() + '\n# changed source\n')
    with pytest.raises(ValueError, match='frozen source drift'):
        generate_policy(original, tmp_path / 'bad.json')
    assert not (tmp_path / 'bad.json').exists()


def test_real_case_registry_contains_translated_position_boundaries_and_recovery():
    from tools.rust_migration.translation_reference import translation_cases
    rows = translation_cases()
    by_id = {row['id']: row for row in rows}
    assert len(by_id) == len(rows)
    for count in (511, 512, 513, 1023, 1024, 1025):
        assert by_id[f'source-boundary{count}']['source_pieces_with_eos'] == count
    assert by_id['error-then-english']['queries'][-1] == 'find the input parser'
    assert by_id['missing-assets-lazy']['missing_assets'] is True
